import java.io.*;import java.util.*;import java.util.zip.*;import java.nio.*;
import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.dexbacked.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;import com.android.tools.smali.dexlib2.iface.reference.*;import com.android.tools.smali.dexlib2.immutable.*;import com.android.tools.smali.dexlib2.writer.pool.*;import com.android.tools.smali.dexlib2.writer.io.*;
public class CurrentApkIdentity {
 static String P="Lapp/hiro/oneback/runtime/";static Set<String>targets=new HashSet<>(Arrays.asList("LX/01h;","LX/0Ok;","LX/8Zv;","Landroidx/activity/ComponentActivity;","Lcom/instagram/mainactivity/InstagramMainActivity;"));
 static Map<String,ClassDef> read(String p)throws Exception{Map<String,ClassDef>out=new TreeMap<>();if(p.endsWith(".mpp")){try(ZipFile z=new ZipFile(p)){byte[]b=z.getInputStream(z.getEntry("extensions/oneback_exit.mpe")).readAllBytes();for(ClassDef c:new DexBackedDexFile(Opcodes.getDefault(),ByteBuffer.wrap(b)).getClasses())out.put(c.getType(),c);}return out;}MultiDexContainer<? extends DexFile>d=DexFileFactory.loadDexContainer(new File(p),Opcodes.getDefault());for(String e:d.getDexEntryNames())for(ClassDef c:d.getEntry(e).getDexFile().getClasses())if(c.getType().startsWith(P)||targets.contains(c.getType()))out.put(c.getType(),c);return out;}
 static byte[]canonical(ClassDef c)throws Exception{MemoryDataStore m=new MemoryDataStore();DexPool.writeTo(m,new ImmutableDexFile(Opcodes.getDefault(),Collections.singleton(c)));byte[]b=Arrays.copyOf(m.getBuffer(),m.getSize());m.close();return b;}
 static Map<String,ClassDef>rt(Map<String,ClassDef>all){Map<String,ClassDef>r=new TreeMap<>();for(ClassDef c:all.values())if(c.getType().startsWith(P))r.put(c.getType(),c);return r;}
 static void compare(String label,Map<String,ClassDef>a,Map<String,ClassDef>b)throws Exception{
  Set<String>missing=new TreeSet<>(b.keySet());missing.removeAll(a.keySet());Set<String>extra=new TreeSet<>(a.keySet());extra.removeAll(b.keySet());int exact=0,equal=0,unequal=0;List<String>deltas=new ArrayList<>();
  for(ClassDef c:b.values()){ClassDef n=a.get(c.getType());if(n==null)continue;if(Arrays.equals(canonical(c),canonical(n)))exact++;boolean same=true;try{SemanticApkAudit.classMeta(c,n);}catch(AssertionError f){same=false;deltas.add(f.getMessage());}Map<String,Method>x=SemanticApkAudit.methods(c),y=SemanticApkAudit.methods(n);if(!x.keySet().equals(y.keySet())){same=false;deltas.add(c.getType()+" method inventory");}for(String key:x.keySet()){if(!y.containsKey(key))continue;try{SemanticApkAudit.methodMeta(x.get(key),y.get(key));if(!SemanticApkAudit.code(x.get(key)).equals(SemanticApkAudit.code(y.get(key))))throw new AssertionError(key+" executable delta");}catch(AssertionError f){same=false;if(deltas.size()<20)deltas.add(f.getMessage());}}if(same)equal++;else unequal++;}
  System.out.println(label+" runtime classes: actual="+a.size()+" reference="+b.size()+" canonicalByteEqual="+exact+" semanticEqual="+equal+" semanticUnequal="+unequal+" missing="+missing+" extra="+extra);System.out.println("  firstDeltas="+deltas);
 }
 public static void main(String[]a)throws Exception{Map<String,ClassDef>now=read(a[0]);System.out.println("CURRENT "+a[0]);for(int i=1;i<a.length;i++)compare(a[i],rt(now),rt(read(a[i])));
  for(ClassDef c:now.values())if(targets.contains(c.getType()))for(Method m:c.getMethods())if(m.getImplementation()!=null){int n=0;for(Instruction ins:m.getImplementation().getInstructions()){if(ins instanceof ReferenceInstruction){Reference r=((ReferenceInstruction)ins).getReference();if(r instanceof MethodReference&&((MethodReference)r).getDefiningClass().startsWith(P))System.out.println("HOOK "+m+" instruction="+n+" "+ins.getOpcode()+" "+r);}n++;}}
 }
}
